'use strict';
// Curated portfolio guide. No LLM, network calls, cookies, or conversation storage.
(()=>{
const answers=[
 {id:'experience',q:"What is Nitish's Product Management experience?",keys:['experience','background','career','years','history'],text:'Nitish has 10 years of Product Management experience across Bajaj Finance, IIFL Finance, and Data Axle Solutions. His work spans lending, enterprise SaaS, AI-enabled capabilities, roadmap ownership, and cross-functional delivery.',link:'#experience',label:'Explore the career journey'},
 {id:'impact',q:'What measurable business outcomes has he delivered?',keys:['impact','outcomes','metrics','revenue','customers','results','business value'],text:'At Data Axle, the products managed have $40M+ combined annual revenue and 50,000+ customers; these are product-scale figures. GenAI email content reduced campaign creation time by 30%, and ML audience recommendations reduced audience identification time by 10%. At Bajaj Finance, predictive hiring reduced collection delays by 30% and Salesforce CRM reached 100% adoption across Sales and Operations.',link:'#case-studies',label:'View the evidence in case studies'},
 {id:'ai',q:'What AI and data products has he worked on?',keys:['ai','genai','ml','data','llm','artificial intelligence','machine learning','content','audience'],text:'Professionally at Data Axle, Nitish delivered GenAI-powered Smart Content Generation for email copy (30% less campaign creation time) and ML-powered Smart Audience Recommendation (10% less audience identification time). Independent BuyWise work uses deterministic calculations and rules; local LLM experimentation is optional and is distinct from production AI delivery.',link:'#case/genai',label:'Read the GenAI case study'},
 {id:'saas',q:'What experience does he have in enterprise SaaS?',keys:['saas','enterprise','platform','roadmap','api','integration','genie'],text:'At Data Axle, Nitish owns roadmaps and requirements across two B2B SaaS products, with customer discovery, market research, CRM/API integrations, GTM, and adoption work. Documented outcomes include 15+ annual releases, 95% sprint predictability, and the Genie Cloud MVP launch in Q3 2022.',link:'#case/enterprise',label:'Read the enterprise SaaS case study'},
 {id:'fintech',q:'What is his FinTech and lending background?',keys:['fintech','lending','bank','loan','finance','iifl','bajaj','los','lms','commercial','p&l','auction'],text:'IIFL work spanned four platforms supporting a ₹10,000 Cr AUM Gold Loan business, including LOS, loan management, customer and audit workflows, and support for the CSB Bank initiative. The digital Gold Loan channel launched in June 2020 targeting a ₹900 Cr+ business opportunity, not realized revenue. Bajaj experience included Salesforce, auction workflows, predictive hiring, P&L preparation, and business planning.',link:'#case/gold-loan',label:'Read the lending case study'},
 {id:'products',q:'What products has he independently built?',keys:['independent','built','projects','lab','buywise','carenest','prototype','demo','technical'],text:'BuyWise is a working local purchase-decision prototype using Python, FastAPI, PostgreSQL, and a rule-based recommendation engine. BuyWise Lite is a public web prototype iterated through early tester feedback. CareNest is a private household-maintenance prototype with recurring task workflows. These are independent experiments, with no claimed commercial traction or production-scale adoption.',link:'#product-lab',label:'Explore Product Lab and demo links'},
 {id:'leadership',q:'What leadership responsibilities has he handled?',keys:['leadership','responsibilities','team','manage','reports','people','lead'],text:'The verified portfolio documents roadmap and investment decisions, discovery, requirements, stakeholder alignment, UAT, rollout, GTM, and cross-functional delivery. IIFL work also included vendors and technology partners. It does not establish direct-report counts or organizational size, so this guide cannot verify those.',link:'#experience',label:'Explore ownership across roles'},
 {id:'principal',q:'Why might he be suitable for a Principal Product Manager role?',keys:['principal','suitable','fit','senior','group','hire'],text:'Relevant evidence includes enterprise SaaS roadmap ownership, commercial grounding in lending and P&L work, AI-enabled workflow delivery, platform integrations, and independent product experimentation. These may be relevant to senior product roles; suitability depends on the role’s specific strategic scope and expectations. This is an evidence summary, not a verified hiring assessment.',link:'#case-studies',label:'Assess the professional work'},
 {id:'contact',q:'How can I contact Nitish?',keys:['contact','email','linkedin','connect'],text:'Use the email and LinkedIn options in the Contact section to connect with Nitish directly.',link:'#contact',label:'Contact Nitish'}
];
const widget=document.createElement('aside');widget.className='ask-widget';widget.setAttribute('aria-label','Ask Nitish portfolio guide');widget.innerHTML=`<button class="ask-launch" aria-expanded="false" aria-controls="ask-panel">Ask Nitish <span aria-hidden="true">↗</span></button><section class="ask-panel" id="ask-panel" hidden aria-labelledby="ask-title"><div class="ask-heading"><div><h2 id="ask-title">Ask Nitish</h2><p>Curated portfolio guide · no generative AI</p></div><button class="ask-close" aria-label="Close Ask Nitish">×</button></div><p class="ask-intro">Explore my work through verified portfolio content.</p><div class="ask-suggestions" aria-label="Suggested questions">${answers.slice(0,8).map(a=>`<button data-answer="${a.id}">${a.q}</button>`).join('')}</div><div class="ask-response" role="status" aria-live="polite" aria-atomic="true"></div><form class="ask-form"><label for="ask-question">Your question</label><div><input id="ask-question" type="text" maxlength="250" autocomplete="off" placeholder="Ask about SaaS, AI, lending…"><button type="submit">Ask</button></div></form><small class="ask-privacy">Questions stay in this page. Nothing is saved or sent.</small></section>`;document.body.append(widget);
const launch=widget.querySelector('.ask-launch'),panel=widget.querySelector('.ask-panel'),input=widget.querySelector('input'),response=widget.querySelector('.ask-response');
function toggle(open){panel.hidden=!open;launch.setAttribute('aria-expanded',String(open));if(open)input.focus();else launch.focus()}
launch.addEventListener('click',()=>toggle(panel.hidden));widget.querySelector('.ask-close').addEventListener('click',()=>toggle(false));widget.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden){toggle(false);e.stopPropagation()}});
function answer(a){response.replaceChildren();const p=document.createElement('p');p.textContent=a?.text||'I can’t answer that reliably from the verified portfolio. Try a suggested question or contact Nitish for more detail.';response.append(p);const link=document.createElement('a');link.href=a?.link||'#contact';link.textContent=a?.label||'Contact Nitish';link.onclick=()=>toggle(false);response.append(link);}
widget.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>answer(answers.find(a=>a.id===b.dataset.answer))));
widget.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const query=input.value.toLowerCase().replace(/[^a-z0-9& ]/g,' ');if(!query.trim()){input.focus();return}const scored=answers.map(a=>({a,score:a.keys.reduce((sum,key)=>sum+(new RegExp('(?:^|\\s)'+key.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?:\\s|$)').test(query)?1:0),0)})).sort((a,b)=>b.score-a.score);answer(scored[0].score?scored[0].a:null);input.value='';});
})();
